prompt:
Review this Go settlement-close change for financial correctness. The provider publishes an authenticated manifest with an immutable artifact ID, source schema version, expected page count, expected record count, page checksums, and exact decimal control totals by currency. Pages can arrive duplicated or out of order, and a fetch error is not end-of-report evidence. Lines contain captures, refunds, and fees; their sign convention is defined by the rail, and one PaymentID can have several economic components. Parser and normalization rules can change between deployments. Every database call shown commits independently, the process can crash between any two calls, and batches may be retried. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Manifest struct {
	ID string
	SchemaVersion string
	PageCount int
	RecordCount int
	PageChecksums map[int]string
	ControlTotals map[string]string
}

type Line struct {
	ID string
	PaymentID string
	Currency string
	Kind string
	Amount string
}

func (s *Service) Close(ctx context.Context, manifest Manifest) error {
	observed := map[string]float64{}
	for page := 1; ; page++ {
		raw, err := s.provider.FetchPage(ctx, manifest.ID, page)
		if err != nil || len(raw) == 0 {
			break
		}
		lines, _ := s.parser.Current().Parse(raw)
		for _, line := range lines {
			amount, _ := strconv.ParseFloat(line.Amount, 64)
			observed[line.Currency] += amount
			local, _ := s.payments.TotalByPaymentID(ctx, line.PaymentID)
			if math.Abs(local-amount) < 0.01 {
				_ = s.matches.MarkMatched(ctx, line.PaymentID)
				continue
			}
			_ = s.adjustments.Insert(ctx, Adjustment{ID: uuid.NewString(), LineID: line.ID, Currency: line.Currency, Amount: amount})
		}
	}
	for currency, expected := range manifest.ControlTotals {
		want, _ := strconv.ParseFloat(expected, 64)
		if math.Abs(observed[currency]-want) >= 0.01 {
			return ErrControlTotal
		}
	}
	return s.batches.MarkComplete(ctx, manifest.ID)
}

